async function sendEmailOTP({ email, otp, type }: { email: string; otp: string; type: string }) {
  console.log('[Better Auth] sendVerificationOTP called', {
    email,
    otp,
    type,
    timestamp: new Date().toISOString()
  })

  try {
    if (type === 'email-verification') {
      console.log('[Better Auth] Processing email-verification OTP')
      const templatePath = path.join(
        process.cwd(),
        'emails',
        'email-validation-otp.hbs'
      )
      const templateContent = fs.readFileSync(templatePath, 'utf8')
      const template = Handlebars.compile(templateContent)

      const html = template({
        code: otp
      })

      console.log('[Better Auth] Sending email to', email)
      await sendMail({
        to: email,
        from: env.MAIL_SENDER,
        subject: 'Vérification de votre email',
        html: html
      })
      console.log('[Better Auth] Email sent successfully')
    } else {
      console.log('[Better Auth] OTP type is not email-verification:', type)
    }
  } catch (error) {
    console.error('[Better Auth] Error in sendVerificationOTP:', error)
    throw error
  }
}

export const auth = betterAuth({
  database: prismaAdapter(prisma, {
    provider: 'sqlserver'
  }),
  trustedOrigins: env.TRUSTED_ORIGINS || [],
  databaseHooks: {
    session: {
      create: {
        before: async (session, context) => {
          const activeAccountId = context?.headers?.get('x-active-account-id')

          if (activeAccountId) {
            return {
              data: {
                ...session,
                activeAccountId: activeAccountId
              }
            }
          }

          return false
        }
      }
    },
    verification: {
      create: {
        before: async (verification) => {
          const verificationRecords = await prisma.customerVerification.findMany()
          console.log('verificationRecords', verificationRecords)
          console.log('[Better Auth] Verification create BEFORE hook:', {
            id: verification.id,
            identifier: verification.identifier,
            value: verification.value,
            expiresAt: verification.expiresAt,
            timestamp: new Date().toISOString()
          })
          // Ne pas bloquer la création
          return { data: verification }
        },
        after: async (verification) => {
          console.log('[Better Auth] Verification create AFTER hook:', {
            id: verification.id,
            identifier: verification.identifier,
            type: verification.identifier?.includes('email-verification') ? 'email-verification' : 'other',
            timestamp: new Date().toISOString()
          })

          try {
            const exists = await prisma.customerVerification.findUnique({
              where: { id: verification.id }
            })
            console.log('exists', exists)
            console.log('[Better Auth] Verification record exists in DB:', !!exists)
          } catch (error) {
            console.error('[Better Auth] Error checking verification in DB:', error)
          }

          if (verification.identifier?.includes('email-verification-otp-')) {
            const email = verification.identifier.replace('email-verification-otp-', '')
            const otp = verification.value.split(':')[0]

            console.log('[Better Auth] Manually calling sendVerificationOTP from hook')
            sendEmailOTP({
              email,
              otp,
              type: 'email-verification'
            }).catch((error) => {
              console.error('[Better Auth] Error in manual sendVerificationOTP call:', error)
            })
          }
        }
      }
    }
  },
  user: {
    modelName: 'CustomerUser',
    deleteUser: {
      enabled: true
    }
  },
  session: {
    modelName: 'CustomerSession',
    additionalFields: {
      activeAccountId: {
        type: 'string',
        required: true,
        description: 'The ID of the selected Salesforce account'
      }
    }
  },
  account: {
    modelName: 'CustomerAccount'
  },
  verification: {
    modelName: 'CustomerVerification'
  },
  emailAndPassword: {
    enabled: true
  },
  plugins: [
    emailOTP({
      async sendVerificationOTP({ email, otp, type }) {
        // but it is also called manually from the verification.create.after hook
        // due to an issue with Prisma V7
        console.log('sendVerificationOTP by Better Auth', email, otp, type) // NEVER REACHED
        return await sendEmailOTP({ email, otp, type })
      }
    })
  ]
})
```

